def _field_should_be_altered(self, old_field, new_field, ignore=None):
    # Return False if both fields are non-concrete and not many-to-many
    if not old_field.concrete and not old_field.many_to_many:
        if not new_field.concrete and not new_field.many_to_many:
            return False

    ignore = ignore or set()
    _, old_path, old_args, old_kwargs = old_field.deconstruct()
    _, new_path, new_args, new_kwargs = new_field.deconstruct()

    # Remove ignored attributes from both old and new field keyword arguments
    for attr in ignore.union(old_field.non_db_attrs):
        old_kwargs.pop(attr, None)
    for attr in ignore.union(new_field.non_db_attrs):
        new_kwargs.pop(attr, None)

    # Handle foreign key db_table change
    if not new_field.many_to_many:
        if old_field.remote_field and new_field.remote_field:
            if (old_field.remote_field.model._meta.db_table ==
                new_field.remote_field.model._meta.db_table):
                old_kwargs.pop("to", None)
                new_kwargs.pop("to", None)

    # Handle db_default equality
    if old_kwargs.get("db_default") and new_kwargs.get("db_default"):
        if self.db_default_sql(old_field) == self.db_default_sql(new_field):
            old_kwargs.pop("db_default")
            new_kwargs.pop("db_default")

    # Check column name differences or differences in deconstructed parts
    return (
        (old_field.concrete and new_field.concrete and
         self.quote_name(old_field.column) != self.quote_name(new_field.column)) or
        (old_path, old_args, old_kwargs) != (new_path, new_args, new_kwargs)
    )
